from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];J=R/'judge/guangying-she'
def save(p,d):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf8')
cfg=json.loads((R/'configs/dengta-jushe.json').read_text(encoding='utf8'))
cfg.update(id='guangying-she',model_visible={'title':'光影摄影社 · 相册驿站','intro':'选择全自助观展模式，依据站内资料复原第3届影展的八个展位，并进入开幕之夜。只使用正常界面与站内材料。'},entry_url='http://127.0.0.1:8812/index.html',allow_hosts=['127.0.0.1:8812'],judge_path='judge/guangying-she/judge.json',notes_for_report=['Self-service hintMode off required. One critical eight-photo ordering gate; darkroom password is optional, not route-required. One unranked original ending.'])
cfg['local_serve'].update(command=['python','scripts/serve_static.py','--root','tasks/guangying-she/mirror','--port','8812','--host','0.0.0.0'],ready_url=cfg['entry_url'],port=8812)
save(R/'configs/guangying-she.json',cfg)
prefix='(()=>{try{const s=JSON.parse(localStorage.getItem("lhs2008save-v1"));return !!s && s.hintMode==="off" && '
order='JSON.stringify(s.slots)===JSON.stringify(["p1","p2","p3","p4","p5","p6","p7","p8"])'
exprs={'darkroom':'s.darkroom===true','wall':'s.solved===true && s.checkedCount>0 && '+order,'ending':'s.solved===true && s.checkedCount>0 && '+order+' && location.hash==="#/opening" && document.body.innerText.includes("名 誉 观 展 证")'}
save(J/'judge.json',{'hooks':{k:{'type':'js_truthy','expr':prefix+'('+v+')}catch{return false}})()'} for k,v in exprs.items()},'checkpoints':[{'id':'wall','hook':'wall','op':'truthy'},{'id':'darkroom','hook':'darkroom','op':'truthy','role':'optional'}],'routes':[{'id':'reopened-exhibition','gates':['wall'],'ending':{'hook':'ending','op':'truthy'}}]})
save(J/'checkpoint-spec.json',{'critical':[{'id':'wall','condition':'All eight unique chosen photographs placed in chronology p1..p8 and normal check succeeds.','prerequisites':[],'latch':'Harness checkpoint latches during one episode; new judge required after reset.','reasoning':'Cross-reference renamed attachments, original time codes, incorrect caption, exclusions and chronological memo. Memo itself directly lists the result, so difficulty low.'}],'optional':[{'id':'darkroom','answer':'灯河纪事','condition':'Exact trimmed four-character current exhibition theme','not_required':'Wall allows arranging before login; no false route prerequisite.'}],'ending':{'count':1,'tier':'unclassified','condition':'Solved wall plus opening page displaying certificate; no original bad-ending route.'},'non_scoring':['pins','visits','search/filter','guestbook','certificate name','print','older exhibitions','hint clicks'],'failure_branches':['wrong password','incomplete wall','wrong wall with per-slot green feedback','opening locked when unsolved','empty guestbook rejected'],'modes':['on: guide can reveal full answer; benchmark requires off','off: no guide but same puzzle and ending']})
print('Config and independent declarative judge saved.')
